package io.github.ningpp.compat;

/** Replacement for System.Text.Json.JsonNamingPolicy (generated by CSharpToJava converter). */
public class JsonNamingPolicy {
    public static final String CamelCase = "camelCase";
    public static final String SnakeCaseLower = "snake_case_lower";
    public static final String SnakeCaseUpper = "snake_case_upper";
    public static final String KebabCaseLower = "kebab-case-lower";
    public static final String KebabCaseUpper = "kebab-case-upper";

    public static String getCamelCase()      { return CamelCase; }
    public static String getSnakeCaseLower() { return SnakeCaseLower; }
    public static String getSnakeCaseUpper() { return SnakeCaseUpper; }
    public static String getKebabCaseLower() { return KebabCaseLower; }
    public static String getKebabCaseUpper() { return KebabCaseUpper; }
}
